/* Markup: <div class="fx-magnetic" role="img" aria-label="MAGNET"><b aria-hidden="true" style="--i:0">M</b><b aria-hidden="true" style="--i:1">A</b><b aria-hidden="true" style="--i:2">G</b><b aria-hidden="true" style="--i:3">N</b><b aria-hidden="true" style="--i:4">E</b><b aria-hidden="true" style="--i:5">T</b></div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 39 Magnetic */
.fx-magnetic {
  font: 600 30px/1.1 JetBrains Mono, monospace;
  letter-spacing: .06em;
  color: var(--ink);
  display: inline-flex;
}
.fx-magnetic b {
  font-weight: inherit;
  display: inline-block;
  text-shadow: 0 0 0 var(--ink-2);
  animation: fx-magnetic 2.7s ease-in-out infinite;
  animation-delay: calc(var(--i) * .07s);
}
.fx-magnetic b:nth-child(odd) {
  color: var(--ink-3);
}
@keyframes fx-magnetic {
  0%,to {
    transform: translate(0) scale(1);
    text-shadow: 0 0 0 transparent;
  }
  42% {
    transform: translate(calc((3 - var(--i)) * 2px)) scale(1.12);
    text-shadow: 0 0 16px color-mix(in srgb, var(--ink-2) 70%, transparent);
  }
  62% {
    transform: translate(calc((var(--i) - 3) * 3px)) scale(.96);
  }
}
